INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l1','hand down','',NULL,'/hænd daʊn/','Legends are handed down from parents to children.','传说由父母传给孩子。','The watch was handed down through the family.','这块表在家族里代代相传。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l1','find out','',NULL,'/faɪnd aʊt/','Archaeologists try to find out where people came from.','考古学家设法查明人们的来历。','We found out the truth later.','后来我们查明了真相。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l1','rot away','',NULL,'/rɑːt əˈweɪ/','Wooden tools have rotted away over time.','木器随岁月腐烂殆尽。','The old fence slowly rotted away.','旧栅栏慢慢烂掉了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l1','without a trace','',NULL,'/wɪˈðaʊt ə treɪs/','The bones disappeared without a trace.','那些骨头消失得无影无踪。','The ship vanished without a trace.','那艘船消失得无影无踪。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',5,'am4_l1_gp1','choice','{"stem":"\"We can read of things ___ happened thousands of years ago.\"(定语从句,指物,作主语)","options":["whose","that","what","who"],"answer_index":1,"stem_cn":"我们能读到几千年前发生的事。","explanation_cn":"定语从句,先行词 things 指物,that 在从句中作主语。✓ things that happened thousands of years ago. ✗ who(指人)/ what(不引导定从)/ whose(所属):指物用 that。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',5,'am4_l1_gp1','choice','{"stem":"\"Anthropologists ___ wondered about our ancestors studied old legends.\"(定语从句,指人,作主语)","options":["who","which","whom","what"],"answer_index":0,"stem_cn":"那些琢磨我们祖先来历的人类学家研究古老传说。","explanation_cn":"定语从句,先行词 Anthropologists 指人,who 作从句主语。✓ Anthropologists who wondered… ✗ which(指物)/ whom(作宾语)/ what:指人作主语用 who。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',5,'am4_l1_gp1','choice','{"stem":"\"The only way ___ they could keep history was to recount it.\"(定语从句,指方式,关系词)","options":["what","who","whose","that"],"answer_index":3,"stem_cn":"他们保存历史的唯一办法就是口口相传。","explanation_cn":"定语从句修饰 the only way,关系词用 that(表方式的先行词常用 that)。✓ the only way that they could keep history. ✗ what / who / whose:此处用 that。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',5,'am4_l1_gp2','choice','{"stem":"\"Sagas are legends ___ down from one generation to the next.\"(过去分词作定语,被动“被传下”)","options":["handing","hand","handed","to hand"],"answer_index":2,"stem_cn":"萨迦是代代相传的传说。","explanation_cn":"过去分词作定语,表被动“被传下来”,修饰 legends。✓ legends handed down from one generation to the next. ✗ handing(主动)/ hand / to hand:表被动用过去分词 handed。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',5,'am4_l1_gp2','choice','{"stem":"\"A bone ___ in rock may survive for millions of years.\"(过去分词作定语,被动“被埋”)","options":["buried","bury","to bury","burying"],"answer_index":0,"stem_cn":"埋在岩石里的骨头可存续数百万年。","explanation_cn":"过去分词作定语,表被动“被埋”,修饰 bone。✓ a bone buried in rock. ✗ burying(主动)/ bury / to bury:表被动用过去分词 buried。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',5,'am4_l1_gp2','choice','{"stem":"\"From a few ___ flints, much can be learned.\"(过去分词作定语,“加工过的”)","options":["working","worked","work","to work"],"answer_index":1,"stem_cn":"从几片加工过的燧石就能了解很多。","explanation_cn":"过去分词作定语,“被加工过的”,修饰 flints。✓ a few worked flints. ✗ working(主动)/ work / to work:表被动/完成用过去分词 worked。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',5,'am4_l1_gp3','choice','{"stem":"\"Anthropologists wondered ___ the ancestors came from.\"(宾语从句,填疑问副词“从哪里”)","options":["where","which","that","what"],"answer_index":0,"stem_cn":"人类学家想知道祖先从何而来。","explanation_cn":"疑问副词 where 引导从句,“从哪里来”;用陈述语序。✓ wondered where the ancestors came from. ✗ which / that / what:问“哪里”用 where。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',5,'am4_l1_gp3','choice','{"stem":"\"Archaeologists try to find out ___ the earliest humans lived.\"(疑问词从句,填‘哪里’)","options":["so","whose","where","that"],"answer_index":2,"stem_cn":"考古学家设法查明最早的人类住在哪里。","explanation_cn":"疑问副词 where 引导从句,“住在哪里”。✓ find out where the earliest humans lived. ✗ whose / that / so:问地点用 where。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',5,'am4_l1_gp3','choice','{"stem":"\"No one could write down ___ those people did.\"(宾语从句,填‘什么’)","options":["whom","what","which","whose"],"answer_index":1,"stem_cn":"没人能记下那些人做过什么。","explanation_cn":"疑问代词 what 引导从句,作 did 的宾语,“做了什么”。✓ write down what those people did. ✗ which / whom / whose:问“什么”用 what。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',5,'am4_l1_gp4','choice','{"stem":"\"Early people ___ have used wood and skins, though none survive.\"(对过去的推测“可能…过”,填情态词)","options":["will","need","may","shall"],"answer_index":2,"stem_cn":"早期的人也许用过木头和兽皮,尽管都没留存。","explanation_cn":"may + have + 过去分词,对过去作推测“可能…过”。✓ Early people may have used wood and skins. ✗ will / shall / need:表推测用 may。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',5,'am4_l1_gp4','choice','{"stem":"\"The wooden tools ___ rotted away long ago.\"(现在完成时,填助动词)","options":["has","have","had","having"],"answer_index":1,"stem_cn":"那些木器早已腐烂殆尽。","explanation_cn":"现在完成时 have + 过去分词,主语 tools(复数)用 have。✓ The wooden tools have rotted away. ✗ has(单数)/ had(过去完成)/ having:复数用 have。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',5,'am4_l1_gp4','choice','{"stem":"\"The stone tools ___ remained while the bones disappeared.\"(现在完成时,与 bones 对比,填助动词)","options":["have","was","were","has"],"answer_index":0,"stem_cn":"石器留存下来,骨头却消失了。","explanation_cn":"现在完成时 have + 过去分词,主语 tools 复数用 have。✓ The stone tools have remained. ✗ has / was / were:现在完成用 have + 过去分词。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',5,'am4_l1_gp5','choice','{"stem":"\"Flint is ___ to shape than most other kinds of stone.\"(比较级“更容易”,填形容词比较级)","options":["more easy","easiest","easy","easier"],"answer_index":3,"stem_cn":"燧石比多数别的石头更容易加工。","explanation_cn":"比较级“更容易”:easy → easier(与 than 呼应)。✓ easier to shape than most other kinds. ✗ easy(原级)/ easiest(最高级)/ more easy(不合规则):双音节以 y 结尾变 easier。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',5,'am4_l1_gp5','choice','{"stem":"\"Archaeologists have ___ history nor legend to guide them.\"(‘既不…也不…’,填与 nor 搭配的前一个词)","options":["not","neither","both","either"],"answer_index":1,"stem_cn":"考古学家既无历史也无传说可循。","explanation_cn":"neither … nor …,“既不…也不…”;与 nor 呼应的前一个词是 neither。✓ neither history nor legend. ✗ either / both / not:与 nor 搭配用 neither。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',5,'am4_l1_gp5','choice','{"stem":"\"Stone lasts ___ than wood or skin.\"(比较级“更久”,填 long 的比较级)","options":["longer","more long","long","longest"],"answer_index":0,"stem_cn":"石头比木头或兽皮存留得更久。","explanation_cn":"比较级“更久”:long → longer(与 than 呼应)。✓ Stone lasts longer than wood or skin. ✗ long(原级)/ longest(最高级)/ more long(不合规则):单音节加 -er。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',5,'am4_l1_gp6','choice','{"stem":"\"The hardened remains of an ancient living thing preserved in rock is a ___.\"(“化石”用哪个词)","options":["statue","fossil","shell","coin"],"answer_index":1,"stem_cn":"古生物在岩石中保存下来的硬化遗骸。","explanation_cn":"古生物在岩石中保存下来的硬化遗骸是 fossil。✓ a bone survives as a fossil. ✗ statue 雕像;✗ coin 硬币;✗ shell 贝壳——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',5,'am4_l1_gp6','choice','{"stem":"\"A person who studies ancient peoples through their remains is an ___.\"(“考古学家”用哪个词)","options":["archaeologist","farmer","engineer","lawyer"],"answer_index":0,"stem_cn":"通过遗物研究古代民族的人。","explanation_cn":"通过遗物研究古代民族的人是 archaeologist。✓ archaeologists have neither history nor legend. ✗ engineer 工程师;✗ lawyer 律师;✗ farmer 农民——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',5,'am4_l1_gp6','choice','{"stem":"\"To tell a story in detail is to ___ it.\"(“讲述、叙述”用哪个词)","options":["forget","hide","invent","recount"],"answer_index":3,"stem_cn":"详细地讲述一个故事。","explanation_cn":"详细地讲述一个故事是 recount。✓ recount it aloud as sagas. ✗ forget 忘记;✗ hide 隐藏;✗ invent 编造——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',6,NULL,'choice','{"stem":"fossil 的意思是:","options":["化石","雕像","硬币","贝壳"],"answer_index":0,"explanation_cn":"fossil = 化石。✓ survives as a fossil 以化石形式保存。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',6,NULL,'choice','{"stem":"saga 的意思是:","options":["歌曲","笑话","萨迦,英雄传说","谜语"],"answer_index":2,"explanation_cn":"saga = 萨迦、(北欧)英雄传说。✓ handed down as sagas 作为萨迦流传。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',6,NULL,'choice','{"stem":"migration 的意思是:","options":["繁荣","隐藏","定居","迁徙,迁移"],"answer_index":3,"explanation_cn":"migration = 迁徙、迁移。✓ the migrations of peoples 民族的迁徙。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',6,NULL,'choice','{"stem":"ancestor 的意思是:","options":["祖先","邻居","后代","陌生人"],"answer_index":0,"explanation_cn":"ancestor = 祖先。✓ the distant ancestors 遥远的祖先。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',6,NULL,'choice','{"stem":"flint 的意思是:","options":["沙子","燧石","木炭","黏土"],"answer_index":1,"explanation_cn":"flint = 燧石。✓ tools of stone, especially flint 石器,尤其是燧石。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',6,NULL,'choice','{"stem":"rot 的意思是:","options":["闪光","生长","漂浮","腐烂"],"answer_index":3,"explanation_cn":"rot = 腐烂。✓ have long since rotted away 早已腐烂殆尽。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',7,NULL,'cloze','{"stem":"第 1 空","context":"We can read of things ___1___ happened long ago in a few early lands. Elsewhere, legends handed ___2___ by storytellers are our only record. Anthropologists wondered ___3___ the Polynesians came from. Early people ___4___ have used wood, but it has rotted away.","blank_no":1,"options":["that","who","what","whose"],"answer_index":0,"explanation_cn":"定语从句,指物 things,that 作从句主语。✓ things that happened long ago."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',7,NULL,'cloze','{"stem":"第 2 空","context":"We can read of things ___1___ happened long ago in a few early lands. Elsewhere, legends handed ___2___ by storytellers are our only record. Anthropologists wondered ___3___ the Polynesians came from. Early people ___4___ have used wood, but it has rotted away.","blank_no":2,"options":["down","up","in","off"],"answer_index":0,"explanation_cn":"hand down,“代代相传”;固定用副词 down。✓ legends handed down by storytellers."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',7,NULL,'cloze','{"stem":"第 3 空","context":"We can read of things ___1___ happened long ago in a few early lands. Elsewhere, legends handed ___2___ by storytellers are our only record. Anthropologists wondered ___3___ the Polynesians came from. Early people ___4___ have used wood, but it has rotted away.","blank_no":3,"options":["where","which","that","what"],"answer_index":0,"explanation_cn":"疑问副词 where 引导从句,“从哪里来”。✓ wondered where the Polynesians came from."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',7,NULL,'cloze','{"stem":"第 4 空","context":"We can read of things ___1___ happened long ago in a few early lands. Elsewhere, legends handed ___2___ by storytellers are our only record. Anthropologists wondered ___3___ the Polynesians came from. Early people ___4___ have used wood, but it has rotted away.","blank_no":4,"options":["may","will","shall","do"],"answer_index":0,"explanation_cn":"may + have + 过去分词,对过去的推测。✓ Early people may have used wood."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',8,NULL,'choice','{"stem":"Why are legends handed down by storytellers useful?","options":["They replace the need for archaeology","They are easy to memorize","They are always completely accurate","They tell us about migrations of peoples who left no written record"],"answer_index":3,"explanation_cn":"录音说这些口传传说之所以有用,是因为它们能透露古代民族的迁徙情况,而那些民族没有留下任何文字记录。✓ migrations, no written record."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',8,NULL,'choice','{"stem":"Why do stone tools survive when wooden ones do not?","options":["Stone does not decay, while wood rots away","Wood was rarely used","Stone was buried deeper","Stone is more valuable"],"answer_index":0,"explanation_cn":"录音说石头不会腐坏,木头却会烂掉,所以石器留存、木器无踪。✓ stone does not decay."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',8,NULL,'choice','{"stem":"Where do the sagas say some Polynesian peoples originally came from?","options":["Australia","Indonesia","The Near East","North America"],"answer_index":1,"explanation_cn":"录音说萨迦表明,一些波利尼西亚人的祖先早在许多世纪前从印度尼西亚渡海而来。✓ from Indonesia."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',9,NULL,'choice','{"stem":"你想说\"我们能读到几千年前发生的事\"(定语从句):","options":["We can read of things happened thousands of years ago.","We can read of things that happened thousands of years ago.","We can read of things they happened thousands of years ago.","We can read of things what happened thousands of years ago."],"answer_index":1,"explanation_cn":"关系词 that 指物,在从句里充当动作的发出者;不用 what、不用 they、也不能省去关系词。✓ things that happened… 场合:说“…的事”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',9,NULL,'choice','{"stem":"你想说\"人类学家想知道祖先从何而来\"(疑问词宾语从句):","options":["Anthropologists wondered where did the ancestors come from.","Anthropologists wondered from where came the ancestors.","Anthropologists wondered where the ancestors came from.","Anthropologists wondered where the ancestors come from."],"answer_index":2,"explanation_cn":"where 引导的从句用陈述语序:疑问词后直接跟“谁 + 动词”,而非疑问语序;不用 where did the ancestors come(不倒装)、不把 from 提前、也不加问号。✓ where the ancestors came from. 场合:间接问“从哪里来”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',9,NULL,'choice','{"stem":"你想说\"早期的人也许用过木头和兽皮\"(对过去的推测):","options":["Early people may have used wood and skins.","Early people may to have used wood and skins.","Early people may used wood and skins.","Early people may have use wood and skins."],"answer_index":0,"explanation_cn":"对过去的推测 may + have + 过去分词 used;不用 may used、不用 may have use、不用 may to have。✓ may have used. 场合:推测过去“可能做过某事”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',10,NULL,'choice','{"stem":"saga 的意思是:","options":["歌曲","萨迦,英雄传说","谜语","笑话"],"answer_index":1,"explanation_cn":"saga = 萨迦、英雄传说。✓ handed down as sagas."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',10,NULL,'choice','{"stem":"flint 的意思是:","options":["木炭","沙子","黏土","燧石"],"answer_index":3,"explanation_cn":"flint = 燧石。✓ tools of stone, especially flint."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',10,NULL,'choice','{"stem":"\"We can read of things ___ happened long ago.\"(定语从句,指物作主语)","options":["who","that","whose","what"],"answer_index":1,"stem_cn":"我们能读到很久以前发生的事。","explanation_cn":"定语从句,指物 things,that 作从句主语。✓ things that happened long ago. ✗ who / what / whose。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',10,NULL,'choice','{"stem":"\"Early people ___ have used wood and skins.\"(对过去的推测“可能…过”)","options":["need","will","shall","may"],"answer_index":3,"stem_cn":"早期的人也许用过木头和兽皮。","explanation_cn":"may + have + 过去分词,对过去的推测“可能…过”。✓ Early people may have used wood and skins. ✗ will / shall / need。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',10,NULL,'choice','{"stem":"\"hand down\" 的意思是:","options":["放下","交出","代代相传","举手"],"answer_index":2,"explanation_cn":"hand down = 代代相传。✓ legends handed down."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',10,NULL,'choice','{"stem":"\"without a trace\" 的意思是:","options":["毫不费力","立刻","沿着小路","不留一丝痕迹"],"answer_index":3,"explanation_cn":"without a trace = 不留一丝痕迹。✓ disappeared without a trace."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',10,NULL,'choice','{"stem":"According to the passage, how did peoples without writing preserve their history?","options":["By reciting it aloud as sagas passed down the generations","By drawing pictures","They could not preserve it at all","By carving it on stone walls"],"answer_index":0,"passage":"How do we learn about people who lived long before anyone could write? In a few parts of the world writing began thousands of years ago, and we can read of things that happened in those distant times. Yet in many places no one wrote anything down, and the only way that a people could keep its history was to recount it aloud, as sagas — long legends handed down from one generation to the next. Such legends are useful, because they can tell us something about the migrations of peoples who lived long ago but left no written record. Anthropologists who wondered where the distant ancestors of the Polynesian islanders came from found part of the answer in these spoken tales, which suggest that some of them sailed from Indonesia many centuries ago. But the very first people, who were much like ourselves, are forgotten, and their sagas, if they ever had any, are lost. So archaeologists have neither history nor legend to help them find out where the earliest humans came from. Now and then a bone survives as a fossil, buried in rock, but such finds are rare. Fortunately, those early people made tools of stone, especially flint, which is easier to shape than most other kinds; they may also have used wood and animal skins, but these have long since rotted away. Stone does not decay, and so the tools that were made so long ago have remained, even though the bones of the men and women who made them have disappeared without a trace. From a handful of worked flints an archaeologist can recount a story that no legend preserved.","explanation_cn":"课文说没有文字的民族靠把历史当作萨迦大声口传、代代相承来保存它。✓ recount aloud as sagas."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',10,NULL,'choice','{"stem":"Why do archaeologists rely on stone tools to study the earliest humans?","options":["Stone tools are beautiful","Wood lasts the longest","Those humans left neither writing nor legends, and stone survives","Bones are easier to find"],"answer_index":2,"passage":"How do we learn about people who lived long before anyone could write? In a few parts of the world writing began thousands of years ago, and we can read of things that happened in those distant times. Yet in many places no one wrote anything down, and the only way that a people could keep its history was to recount it aloud, as sagas — long legends handed down from one generation to the next. Such legends are useful, because they can tell us something about the migrations of peoples who lived long ago but left no written record. Anthropologists who wondered where the distant ancestors of the Polynesian islanders came from found part of the answer in these spoken tales, which suggest that some of them sailed from Indonesia many centuries ago. But the very first people, who were much like ourselves, are forgotten, and their sagas, if they ever had any, are lost. So archaeologists have neither history nor legend to help them find out where the earliest humans came from. Now and then a bone survives as a fossil, buried in rock, but such finds are rare. Fortunately, those early people made tools of stone, especially flint, which is easier to shape than most other kinds; they may also have used wood and animal skins, but these have long since rotted away. Stone does not decay, and so the tools that were made so long ago have remained, even though the bones of the men and women who made them have disappeared without a trace. From a handful of worked flints an archaeologist can recount a story that no legend preserved.","explanation_cn":"课文说最早的人类既没留下文字也没留下传说,而石头不朽,所以考古学家只能靠石器来研究他们。✓ neither writing nor legend, stone survives."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',10,NULL,'choice','{"stem":"What material makes the best-surviving ancient tools?","options":["Flint and other stone","Wood","Woven grass","Animal skin"],"answer_index":0,"audio":"How do we learn about people who lived long before anyone could write? In a few parts of the world writing began thousands of years ago, and we can read of things that happened in those distant times. Yet in many places no one wrote anything down, and the only way that a people could keep its history was to recount it aloud, as sagas — long legends handed down from one generation to the next. Such legends are useful, because they can tell us something about the migrations of peoples who lived long ago but left no written record. Anthropologists who wondered where the distant ancestors of the Polynesian islanders came from found part of the answer in these spoken tales, which suggest that some of them sailed from Indonesia many centuries ago. But the very first people, who were much like ourselves, are forgotten, and their sagas, if they ever had any, are lost. So archaeologists have neither history nor legend to help them find out where the earliest humans came from. Now and then a bone survives as a fossil, buried in rock, but such finds are rare. Fortunately, those early people made tools of stone, especially flint, which is easier to shape than most other kinds; they may also have used wood and animal skins, but these have long since rotted away. Stone does not decay, and so the tools that were made so long ago have remained, even though the bones of the men and women who made them have disappeared without a trace. From a handful of worked flints an archaeologist can recount a story that no legend preserved.","explanation_cn":"课文说远古的人用石头、尤其是燧石打制工具,而石头不腐,是留存最好的材料。✓ flint and stone."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l1',10,NULL,'choice','{"stem":"What happened to the bones of the people who made the oldest tools?","options":["They were kept in museums","They were written about","They turned to flint","They disappeared without a trace"],"answer_index":3,"audio":"How do we learn about people who lived long before anyone could write? In a few parts of the world writing began thousands of years ago, and we can read of things that happened in those distant times. Yet in many places no one wrote anything down, and the only way that a people could keep its history was to recount it aloud, as sagas — long legends handed down from one generation to the next. Such legends are useful, because they can tell us something about the migrations of peoples who lived long ago but left no written record. Anthropologists who wondered where the distant ancestors of the Polynesian islanders came from found part of the answer in these spoken tales, which suggest that some of them sailed from Indonesia many centuries ago. But the very first people, who were much like ourselves, are forgotten, and their sagas, if they ever had any, are lost. So archaeologists have neither history nor legend to help them find out where the earliest humans came from. Now and then a bone survives as a fossil, buried in rock, but such finds are rare. Fortunately, those early people made tools of stone, especially flint, which is easier to shape than most other kinds; they may also have used wood and animal skins, but these have long since rotted away. Stone does not decay, and so the tools that were made so long ago have remained, even though the bones of the men and women who made them have disappeared without a trace. From a handful of worked flints an archaeologist can recount a story that no legend preserved.","explanation_cn":"课文说打制最古老工具的人,连骨头都已消失得无影无踪。✓ disappeared without a trace."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l2',4,1,2,'Spare That Spider','别伤害蜘蛛','与现在相反的虚拟条件(if it were not for / but for + would)、the more…the more 递进比较、it 作形式主语 + 被动(it has been estimated that)/不定式、定语从句(who/that / 介词+关系代词)、nor 引起的否定倒装 + neither…nor / 短语(NCE4 无 KS 页,考点由课文结构自取;原创承载·论蜘蛛因大量捕食昆虫而为人类之友·科普无害;美语化 baseball diamond/fiber;第四册第2课)','你也许会问:我们为什么该把蜘蛛当朋友?答案很简单——它吞食昆虫,而昆虫是人类最危险的敌人之一。要不是有那些以昆虫为食的动物,昆虫很快就会让地球上的生活难以为继:它们会吃光田里的每一茬庄稼,毁掉我们赖以为生的畜群。鸟和别的野兽帮我们吃掉昆虫,可它们全部加起来,消灭的数目也不过是蜘蛛所灭的一个零头。更妙的是,与另一些猎手不同,蜘蛛对我们毫无害处,也从不动我们的东西。蜘蛛并不是昆虫——尽管许多人误以为如此——它甚至和昆虫算不上近亲。几乎一眼就能看出区别:蜘蛛永远有八条腿,而昆虫从不超过六条。到底有多少蜘蛛在为我们效力?一位科学家在乡下一块田里仔细做了一次统计,估算出一英亩地里有两百多万只——大约相当于一个棒球内场那么大的一片地上就有六千只。蜘蛛一年中至少有一半时间在忙着捕杀昆虫。它们是贪吃的家伙,从不满足于一天三餐;据估计,它们一年里消灭的所有昆虫的总重量,会超过全国人口的总重量。我们越了解蜘蛛,就越应当对它心怀感激。','{"q":"Listen and answer — How much of each year do spiders spend killing insects?","options":["At least half the year","Only a few days","The entire year","Only during summer"],"answer_index":0}'::jsonb,'{"title":"虚拟条件 if it were not for / the more…the more / it 形式主语被动 / nor 倒装","intro":"①与现在相反的虚拟:if + 过去式(be 用 were),主句 would + 原形;if it were not for / but for=‘要不是有…’。②the more … the more …,‘越…越…’,两半都用比较级。③it 作形式主语 + 被动:it has been estimated that…;或 + 不定式:it is impossible to do。④定语从句 who/that;介词 + 关系代词 on which。⑤nor + 部分倒装,承接前面的否定:…, nor is it related to one。","table":{"headers":["用法","结构","例子"],"rows":[["虚拟条件","if it were not for …, would …","If it were not for spiders, insects would…"],["递进比较","the more … the more …","The more we learn, the more grateful"],["it 形式主语被动","It has been estimated that …","It has been estimated that…"],["nor 倒装","…, nor + 助/系动词 + 主语","nor is it related to one"]]},"specialRules":[{"rule":"if it were not for = but for = without,引导与现在相反的虚拟条件;be 一律用 were。","mark":"If it were not for / But for"},{"rule":"nor / neither 置于句首承接否定时,后面要部分倒装(助/系动词提到主语前)。","mark":"nor is it related"},{"rule":"美式用词:baseball diamond(棒球内场,英式常举 football pitch)、fiber(纤维,英式 fibre)。本课已按美语写。","mark":"baseball diamond / fiber"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l2',1,NULL,'Why, you might ask, should we think of the spider as a friend? The answer is simple: it devours insects, and insects are among the most dangerous enemies of the human race. If it were not for the creatures that feed on them, insects would soon make life on Earth impossible; they would devour every crop in the fields and destroy the herds on which we depend.','你也许会问:我们为什么该把蜘蛛当朋友?答案很简单——它吞食昆虫,而昆虫是人类最危险的敌人之一。要不是有那些以昆虫为食的动物,昆虫很快就会让地球上的生活难以为继:它们会吃光田里的每一茬庄稼,毁掉我们赖以为生的畜群。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l2',2,NULL,'Birds and other beasts help us by eating insects, but all of them put together kill only a small fraction of the number that spiders destroy. What is more, unlike some of these other hunters, the spider does us no harm at all and leaves our belongings untouched.','鸟和别的野兽帮我们吃掉昆虫,可它们全部加起来,消灭的数目也不过是蜘蛛所灭的一个零头。更妙的是,与另一些猎手不同,蜘蛛对我们毫无害处,也从不动我们的东西。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l2',3,NULL,'A spider is not an insect, as many people wrongly suppose, nor is it even closely related to one. You can tell the difference almost at a glance, for a spider always has eight legs, while an insect never has more than six.','蜘蛛并不是昆虫——尽管许多人误以为如此——它甚至和昆虫算不上近亲。几乎一眼就能看出区别:蜘蛛永远有八条腿,而昆虫从不超过六条。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l2',4,NULL,'How many spiders are busy on our behalf? One scientist who made a careful census of the spiders in a single country field estimated that there were more than two million in a single acre — something like six thousand on a patch of ground the size of a baseball diamond. Spiders work at killing insects for at least half the year.','到底有多少蜘蛛在为我们效力?一位科学家在乡下一块田里仔细做了一次统计,估算出一英亩地里有两百多万只——大约相当于一个棒球内场那么大的一片地上就有六千只。蜘蛛一年中至少有一半时间在忙着捕杀昆虫。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l2',5,NULL,'They are hungry creatures, never content with only three meals a day, and it has been estimated that the weight of all the insects they destroy in one year would be greater than the total weight of all the people in the country. The more we learn about the spider, the more grateful to it we ought to be.','它们是贪吃的家伙,从不满足于一天三餐;据估计,它们一年里消灭的所有昆虫的总重量,会超过全国人口的总重量。我们越了解蜘蛛,就越应当对它心怀感激。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
