INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l2','feed on','',NULL,'/fiːd ɑːn/','Spiders feed on insects.','蜘蛛以昆虫为食。','Owls feed on mice.','猫头鹰以老鼠为食。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l2','at a glance','',NULL,'/ət ə ɡlæns/','You can tell them apart at a glance.','你一眼就能把它们区分开。','She saw the mistake at a glance.','她一眼就看出了错误。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l2','put together','',NULL,'/pʊt təˈɡeðər/','All the birds put together kill fewer insects than spiders.','所有的鸟加起来杀灭的昆虫也比蜘蛛少。','The two teams put together still lost.','两队合起来还是输了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l2','be content with','',NULL,'/bi kənˈtent wɪð/','Spiders are never content with three meals a day.','蜘蛛从不满足于一天三餐。','He is content with a simple life.','他满足于简单的生活。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',5,'am4_l2_gp1','choice','{"stem":"\"If it ___ not for spiders, insects would overrun the world.\"(与现在相反虚拟,‘要不是有…’,填 be 动词的虚拟形式)","options":["are","is","were","was"],"answer_index":2,"stem_cn":"要不是有蜘蛛,昆虫早就泛滥成灾。","explanation_cn":"与现在相反的虚拟条件,if it were not for(要不是有…);be 一律用 were。✓ If it were not for spiders… ✗ was / is / are:虚拟里 be 用 were。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',5,'am4_l2_gp1','choice','{"stem":"\"But for insect-eaters, insects ___ devour every crop.\"(与现在相反虚拟,主句填这个助动词 + 原形)","options":["would","can","will","must"],"answer_index":0,"stem_cn":"若没有食虫动物,昆虫会吃光每一茬庄稼。","explanation_cn":"与现在相反的虚拟,主句用 would + 动词原形。✓ insects would devour every crop. ✗ will(非虚拟)/ can / must:主句用 would。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',5,'am4_l2_gp1','choice','{"stem":"\"If spiders ___ not exist, our harvests would suffer.\"(与现在相反虚拟,if 从句里 do 的过去式)","options":["will","do","did","had"],"answer_index":2,"stem_cn":"如果蜘蛛不存在,我们的收成会受损。","explanation_cn":"与现在相反的虚拟,if 从句用一般过去式;实义动词否定用 did not + 原形。✓ If spiders did not exist… ✗ do(非虚拟)/ will / had:此处用 did not。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',5,'am4_l2_gp2','choice','{"stem":"\"The more we learn about spiders, the ___ grateful we should be.\"(‘越…越…’的递进句型,填 the 后这个比较级)","options":["more","most","very","much"],"answer_index":0,"stem_cn":"我们越了解蜘蛛,就越该感激它。","explanation_cn":"the more … the more …,“越…越…”;第二个 the 后用比较级 more。✓ the more grateful we should be. ✗ most / much / very:递进句型两半都用比较级。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',5,'am4_l2_gp2','choice','{"stem":"\"The weight of the insects destroyed would be ___ than that of all the people.\"(比较级,与 than 呼应,填 great 的比较级)","options":["more great","greatest","greater","great"],"answer_index":2,"stem_cn":"被消灭的昆虫的总重会超过全国人口的总重。","explanation_cn":"比较级,与 than 呼应:great → greater。✓ greater than that of all the people. ✗ great(原级)/ greatest(最高级)/ more great(不合规则)。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',5,'am4_l2_gp2','choice','{"stem":"\"The ___ insects a spider eats, the more useful it is.\"(‘越多…越…’句型,the 后填 many 的比较级)","options":["more","many","most","much"],"answer_index":0,"stem_cn":"蜘蛛吃掉的昆虫越多,就越有用。","explanation_cn":"the more + 名词 … the more …;此处 many 的比较级用 more。✓ The more insects a spider eats… ✗ most / much / many:可数名词用 more。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',5,'am4_l2_gp3','choice','{"stem":"\"___ has been estimated that spiders destroy countless insects.\"(形式主语 + 被动‘据估计…’,填这个代词)","options":["This","It","There","That"],"answer_index":1,"stem_cn":"据估计,蜘蛛消灭了数不清的昆虫。","explanation_cn":"It 作形式主语,真正的主语是后面的 that 从句;固定 It has been estimated that…。✓ It has been estimated that… ✗ That / This / There:形式主语用 It。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',5,'am4_l2_gp3','choice','{"stem":"\"It is impossible ___ count every spider in a field.\"(it 形式主语,真正主语是后面的不定式,填不定式符号)","options":["that","for","to","of"],"answer_index":2,"stem_cn":"要数清一片田里的每只蜘蛛是不可能的。","explanation_cn":"it 作形式主语,真正主语是不定式;填不定式符号 to。✓ It is impossible to count every spider. ✗ for / of / that:此处用 to count。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',5,'am4_l2_gp3','choice','{"stem":"\"It has been ___ that there are millions of spiders in one acre.\"(it has been + 过去分词:被动‘据估计’,填过去分词)","options":["estimate","estimated","estimates","estimating"],"answer_index":1,"stem_cn":"据估计,一英亩地里有数百万只蜘蛛。","explanation_cn":"被动“据估计” = it has been + 过去分词 estimated。✓ It has been estimated that… ✗ estimate / estimating / estimates:has been 后用过去分词。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',5,'am4_l2_gp4','choice','{"stem":"\"Birds are among the creatures ___ feed on insects.\"(定语从句,指动物,作主语)","options":["who","what","whose","that"],"answer_index":3,"stem_cn":"鸟是以昆虫为食的动物之一。","explanation_cn":"定语从句,先行词 creatures 指动物,that 作从句主语。✓ the creatures that feed on insects. ✗ who(此处用 that)/ what / whose:指物/动物用 that。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',5,'am4_l2_gp4','choice','{"stem":"\"The scientist ___ made the census counted the spiders.\"(定语从句,指人,作主语)","options":["who","whom","what","which"],"answer_index":0,"stem_cn":"做那次统计的科学家数了蜘蛛。","explanation_cn":"定语从句,先行词 scientist 指人,who 作从句主语。✓ The scientist who made the census. ✗ which(指物)/ whom(作宾语)/ what:指人作主语用 who。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',5,'am4_l2_gp4','choice','{"stem":"\"The crops ___ which we depend are threatened by insects.\"(介词 + 关系代词,指物)","options":["in","at","on","of"],"answer_index":2,"stem_cn":"我们赖以为生的庄稼受昆虫威胁。","explanation_cn":"介词 + 关系代词:the crops on which we depend;depend on,故介词用 on。✓ the crops on which we depend. ✗ in / at / of:搭配 depend on。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',5,'am4_l2_gp5','choice','{"stem":"\"A spider is not an insect, ___ is it closely related to one.\"(否定句后接‘也不…’引起倒装,填这个连词)","options":["or","but","and","nor"],"answer_index":3,"stem_cn":"蜘蛛不是昆虫,也和昆虫没什么近亲关系。","explanation_cn":"承接前面的否定“也不…”,nor + 部分倒装。✓ …, nor is it closely related to one. ✗ or / and / but:承接否定用 nor。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',5,'am4_l2_gp5','choice','{"stem":"\"You can tell the difference almost at a ___.\"(at a ___:一眼(就),填名词)","options":["glance","look","sight","view"],"answer_index":0,"stem_cn":"几乎一眼就能看出区别。","explanation_cn":"at a glance,“一眼(就)”;固定用名词 glance。✓ tell the difference at a glance. ✗ look / sight / view:固定搭配是 at a glance。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',5,'am4_l2_gp5','choice','{"stem":"\"Spiders are never ___ with only three meals a day.\"(be ___ with:满足于,填形容词)","options":["contently","contents","content","contenting"],"answer_index":2,"stem_cn":"蜘蛛从不满足于一天只吃三顿。","explanation_cn":"be content with,“满足于”;用形容词 content。✓ never content with three meals a day. ✗ contenting / contently / contents:此结构用 content。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',5,'am4_l2_gp6','choice','{"stem":"\"A large four-legged animal is a ___.\"(“兽、野兽”用哪个词)","options":["fish","bird","plant","beast"],"answer_index":3,"stem_cn":"四条腿的大型动物。","explanation_cn":"四条腿的大型动物是 beast。✓ birds and other beasts. ✗ bird 鸟;✗ fish 鱼;✗ plant 植物——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',5,'am4_l2_gp6','choice','{"stem":"\"An official count of a population is a ___.\"(“统计、普查”用哪个词)","options":["census","contest","career","custom"],"answer_index":0,"stem_cn":"对总数进行的官方清点。","explanation_cn":"对总数进行的官方清点是 census。✓ made a careful census of the spiders. ✗ contest 比赛;✗ custom 习俗;✗ career 职业——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',5,'am4_l2_gp6','choice','{"stem":"\"To eat something up hungrily is to ___ it.\"(“吞食”用哪个词)","options":["keep","plant","ignore","devour"],"answer_index":3,"stem_cn":"狼吞虎咽地把某物吃光。","explanation_cn":"狼吞虎咽地把某物吃光是 devour。✓ they would devour every crop. ✗ plant 种植;✗ ignore 忽视;✗ keep 保留——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',6,NULL,'choice','{"stem":"beast 的意思是:","options":["兽,野兽","鸟","鱼","花"],"answer_index":0,"explanation_cn":"beast = 兽、野兽。✓ birds and other beasts 鸟和别的野兽。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',6,NULL,'choice','{"stem":"census 的意思是:","options":["职业","比赛","习俗","(人口/数量)统计"],"answer_index":3,"explanation_cn":"census = (人口/数量)统计、普查。✓ a careful census of the spiders 对蜘蛛的仔细统计。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',6,NULL,'choice','{"stem":"acre 的意思是:","options":["小时","英里","英亩","公斤"],"answer_index":2,"explanation_cn":"acre = 英亩。✓ more than two million in a single acre 一英亩两百多万只。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',6,NULL,'choice','{"stem":"content 的意思是:","options":["满足的","愤怒的","疲惫的","好奇的"],"answer_index":0,"explanation_cn":"content = 满足的。✓ never content with three meals 从不满足于三餐。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',6,NULL,'choice','{"stem":"devour 的意思是:","options":["储存","吞食,狼吞虎咽","丢弃","种植"],"answer_index":1,"explanation_cn":"devour = 吞食、狼吞虎咽。✓ devour every crop 吃光每一茬庄稼。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',6,NULL,'choice','{"stem":"estimate 的意思是:","options":["忘记","隐藏","证明","估计,估算"],"answer_index":3,"explanation_cn":"estimate = 估计、估算。✓ estimated that there were more than two million 估算有两百多万只。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',7,NULL,'cloze','{"stem":"第 1 空","context":"A spider is not an insect, ___1___ is it closely related to one. If it ___2___ not for spiders, insects would overrun the world. It has been ___3___ that millions of them live in a single acre. The more we learn about them, the ___4___ grateful we should be.","blank_no":1,"options":["nor","or","and","but"],"answer_index":0,"explanation_cn":"承接前面的否定,nor + 部分倒装。✓ …, nor is it closely related to one."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',7,NULL,'cloze','{"stem":"第 2 空","context":"A spider is not an insect, ___1___ is it closely related to one. If it ___2___ not for spiders, insects would overrun the world. It has been ___3___ that millions of them live in a single acre. The more we learn about them, the ___4___ grateful we should be.","blank_no":2,"options":["were","was","is","are"],"answer_index":0,"explanation_cn":"与现在相反的虚拟条件,if it were not for,be 用 were。✓ If it were not for spiders…"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',7,NULL,'cloze','{"stem":"第 3 空","context":"A spider is not an insect, ___1___ is it closely related to one. If it ___2___ not for spiders, insects would overrun the world. It has been ___3___ that millions of them live in a single acre. The more we learn about them, the ___4___ grateful we should be.","blank_no":3,"options":["estimated","estimate","estimating","estimates"],"answer_index":0,"explanation_cn":"被动“据估计”,it has been + 过去分词 estimated。✓ It has been estimated that…"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',7,NULL,'cloze','{"stem":"第 4 空","context":"A spider is not an insect, ___1___ is it closely related to one. If it ___2___ not for spiders, insects would overrun the world. It has been ___3___ that millions of them live in a single acre. The more we learn about them, the ___4___ grateful we should be.","blank_no":4,"options":["more","most","much","very"],"answer_index":0,"explanation_cn":"the more … the more …,第二个 the 后用比较级 more。✓ the more grateful we should be."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',8,NULL,'choice','{"stem":"How much of each year do spiders spend killing insects?","options":["At least half the year","A few days","The whole year","Only in summer"],"answer_index":0,"explanation_cn":"录音说蜘蛛一年里至少有一半时间忙于捕杀昆虫。✓ at least half the year."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',8,NULL,'choice','{"stem":"Why does the writer call the spider a friend?","options":["It is gentle to touch","It keeps houses clean","It devours huge numbers of harmful insects","It spins beautiful webs"],"answer_index":2,"explanation_cn":"录音说蜘蛛之所以是人类之友,是因为它吞食大量对我们有害的昆虫。✓ devours huge numbers of insects."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',8,NULL,'choice','{"stem":"How can you tell a spider from an insect at a glance?","options":["A spider has no eyes","A spider has eight legs; an insect never more than six","A spider has wings","A spider is always larger"],"answer_index":1,"explanation_cn":"录音说几乎一眼就能分辨:蜘蛛永远有八条腿,而昆虫从不超过六条。✓ eight legs vs six."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',9,NULL,'choice','{"stem":"你想说\"要不是有蜘蛛,昆虫早就泛滥成灾\"(与现在相反虚拟):","options":["If it were not for spiders, insects would overran the world.","If it were not for spiders, insects would overrun the world.","If it was not for spiders, insects would overrun the world.","If it were not for spiders, insects will overrun the world."],"answer_index":1,"explanation_cn":"与现在相反的虚拟条件:if it were not for(be 用 were),主句 would + 原形 overrun;不用 was、不用 will、不用 overran。✓ If it were not for…, insects would overrun… 场合:说“要不是有…就会…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',9,NULL,'choice','{"stem":"你想说\"做那次统计的科学家数了蜘蛛\"(定语从句):","options":["The scientist who made the census counted the spiders.","The scientist what made the census counted the spiders.","The scientist which made the census counted the spiders.","The scientist made the census counted the spiders."],"answer_index":0,"explanation_cn":"关系词 who 指人,引导修饰 scientist 的从句;不用 which(指物)、不用 what、也不能省去 who。✓ The scientist who made the census… 场合:说“做…的那位科学家”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',9,NULL,'choice','{"stem":"你想说\"蜘蛛不是昆虫,也和昆虫没什么近亲关系\"(否定后倒装):","options":["A spider is not an insect, or is it closely related to one.","A spider is not an insect, nor it is closely related to one.","A spider is not an insect, nor is it closely related to one.","A spider is not an insect, nor is it closely relate to one."],"answer_index":2,"explanation_cn":"承接前面的否定用 nor,并引起部分倒装:is 提到 it 前;不用 nor it is(未倒装)、related 不能变 relate、不用 or。✓ …, nor is it closely related to one. 场合:再补一个“也不…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',10,NULL,'choice','{"stem":"census 的意思是:","options":["职业","(人口/数量)统计","比赛","习俗"],"answer_index":1,"explanation_cn":"census = (人口/数量)统计、普查。✓ a careful census of the spiders."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',10,NULL,'choice','{"stem":"devour 的意思是:","options":["吞食,狼吞虎咽","丢弃","种植","储存"],"answer_index":0,"explanation_cn":"devour = 吞食、狼吞虎咽。✓ devour every crop."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',10,NULL,'choice','{"stem":"\"If it ___ not for spiders, insects would overrun the world.\"(与现在相反虚拟,be 动词虚拟形式)","options":["was","were","are","is"],"answer_index":1,"stem_cn":"要不是有蜘蛛,昆虫早就泛滥成灾。","explanation_cn":"与现在相反的虚拟条件,if it were not for,be 用 were。✓ If it were not for spiders… ✗ was / is / are。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',10,NULL,'choice','{"stem":"\"A spider is not an insect, ___ is it related to one.\"(否定后倒装)","options":["nor","or","but","and"],"answer_index":0,"stem_cn":"蜘蛛不是昆虫,也和昆虫没什么近亲关系。","explanation_cn":"承接前面的否定“也不…”用 nor,并引起部分倒装。✓ …, nor is it related to one. ✗ or / and / but。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',10,NULL,'choice','{"stem":"\"feed on\" 的意思是:","options":["喂养孩子","生长","以…为食","厌倦"],"answer_index":2,"explanation_cn":"feed on = 以…为食。✓ spiders feed on insects."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',10,NULL,'choice','{"stem":"\"at a glance\" 的意思是:","options":["大声地","一眼就(看出)","慢慢地","偶尔"],"answer_index":1,"explanation_cn":"at a glance = 一眼就(看出)。✓ tell the difference at a glance."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',10,NULL,'choice','{"stem":"According to the passage, what would happen without insect-eaters like spiders?","options":["Spiders would multiply","Nothing would change","The weather would worsen","Insects would devour our crops and herds"],"answer_index":3,"passage":"Why, you might ask, should we think of the spider as a friend? The answer is simple: it devours insects, and insects are among the most dangerous enemies of the human race. If it were not for the creatures that feed on them, insects would soon make life on Earth impossible; they would devour every crop in the fields and destroy the herds on which we depend. Birds and other beasts help us by eating insects, but all of them put together kill only a small fraction of the number that spiders destroy. What is more, unlike some of these other hunters, the spider does us no harm at all and leaves our belongings untouched. A spider is not an insect, as many people wrongly suppose, nor is it even closely related to one. You can tell the difference almost at a glance, for a spider always has eight legs, while an insect never has more than six. How many spiders are busy on our behalf? One scientist who made a careful census of the spiders in a single country field estimated that there were more than two million in a single acre — something like six thousand on a patch of ground the size of a baseball diamond. Spiders work at killing insects for at least half the year. They are hungry creatures, never content with only three meals a day, and it has been estimated that the weight of all the insects they destroy in one year would be greater than the total weight of all the people in the country. The more we learn about the spider, the more grateful to it we ought to be.","explanation_cn":"课文说要不是有以昆虫为食的动物,昆虫会吃光庄稼、毁掉畜群,让生活难以为继。✓ devour crops and herds."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',10,NULL,'choice','{"stem":"How many spiders did the scientist estimate lived in a single acre?","options":["More than two million","Too few to count","Exactly six","About a thousand"],"answer_index":0,"passage":"Why, you might ask, should we think of the spider as a friend? The answer is simple: it devours insects, and insects are among the most dangerous enemies of the human race. If it were not for the creatures that feed on them, insects would soon make life on Earth impossible; they would devour every crop in the fields and destroy the herds on which we depend. Birds and other beasts help us by eating insects, but all of them put together kill only a small fraction of the number that spiders destroy. What is more, unlike some of these other hunters, the spider does us no harm at all and leaves our belongings untouched. A spider is not an insect, as many people wrongly suppose, nor is it even closely related to one. You can tell the difference almost at a glance, for a spider always has eight legs, while an insect never has more than six. How many spiders are busy on our behalf? One scientist who made a careful census of the spiders in a single country field estimated that there were more than two million in a single acre — something like six thousand on a patch of ground the size of a baseball diamond. Spiders work at killing insects for at least half the year. They are hungry creatures, never content with only three meals a day, and it has been estimated that the weight of all the insects they destroy in one year would be greater than the total weight of all the people in the country. The more we learn about the spider, the more grateful to it we ought to be.","explanation_cn":"课文说一位科学家估算,一英亩地里有两百多万只蜘蛛。✓ more than two million."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',10,NULL,'choice','{"stem":"For roughly how long each year are spiders busy killing insects?","options":["One week","Only at night","At least half the year","All twelve months"],"answer_index":2,"audio":"Why, you might ask, should we think of the spider as a friend? The answer is simple: it devours insects, and insects are among the most dangerous enemies of the human race. If it were not for the creatures that feed on them, insects would soon make life on Earth impossible; they would devour every crop in the fields and destroy the herds on which we depend. Birds and other beasts help us by eating insects, but all of them put together kill only a small fraction of the number that spiders destroy. What is more, unlike some of these other hunters, the spider does us no harm at all and leaves our belongings untouched. A spider is not an insect, as many people wrongly suppose, nor is it even closely related to one. You can tell the difference almost at a glance, for a spider always has eight legs, while an insect never has more than six. How many spiders are busy on our behalf? One scientist who made a careful census of the spiders in a single country field estimated that there were more than two million in a single acre — something like six thousand on a patch of ground the size of a baseball diamond. Spiders work at killing insects for at least half the year. They are hungry creatures, never content with only three meals a day, and it has been estimated that the weight of all the insects they destroy in one year would be greater than the total weight of all the people in the country. The more we learn about the spider, the more grateful to it we ought to be.","explanation_cn":"课文说蜘蛛一年里至少有一半时间在捕杀昆虫。✓ at least half the year."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l2',10,NULL,'choice','{"stem":"How does the spider compare with birds and beasts at killing insects?","options":["Spiders kill the fewest","Spiders kill far more than all of them put together","Spiders kill none at all","They kill exactly the same number"],"answer_index":1,"audio":"Why, you might ask, should we think of the spider as a friend? The answer is simple: it devours insects, and insects are among the most dangerous enemies of the human race. If it were not for the creatures that feed on them, insects would soon make life on Earth impossible; they would devour every crop in the fields and destroy the herds on which we depend. Birds and other beasts help us by eating insects, but all of them put together kill only a small fraction of the number that spiders destroy. What is more, unlike some of these other hunters, the spider does us no harm at all and leaves our belongings untouched. A spider is not an insect, as many people wrongly suppose, nor is it even closely related to one. You can tell the difference almost at a glance, for a spider always has eight legs, while an insect never has more than six. How many spiders are busy on our behalf? One scientist who made a careful census of the spiders in a single country field estimated that there were more than two million in a single acre — something like six thousand on a patch of ground the size of a baseball diamond. Spiders work at killing insects for at least half the year. They are hungry creatures, never content with only three meals a day, and it has been estimated that the weight of all the insects they destroy in one year would be greater than the total weight of all the people in the country. The more we learn about the spider, the more grateful to it we ought to be.","explanation_cn":"课文说鸟和别的野兽全部加起来,消灭的昆虫也只是蜘蛛所灭的一个零头。✓ spiders kill far more."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
